#!/bin/sh
# gen-hwstatus.sh -- generate internal/hwstatus/results.tsv from the hardware
# status table in befunde/RESULTS.md of the driver repository
# (github.com/SirRenix/minisforum-n5pro-fan-proxmox). RESULTS.md is the only
# source of the hardware status; n5-fangov embeds the generated file.
#
# Usage: tools/gen-hwstatus.sh <path/to/RESULTS.md> [output]
#        (default output: internal/hwstatus/results.tsv, run from the repo root)
#
# The table sits between "<!-- hwstatus:begin -->" and "<!-- hwstatus:end -->"
# and has 8 columns: product | board | bios | ec | status | origin | date | note.
# Backticks are stripped, cells trimmed. A row with another column count, an
# unknown status, or validated/tested with an origin other than "eigen" fails
# the run; nothing is written then.
set -eu

src=${1:-}
out=${2:-internal/hwstatus/results.tsv}
if [ -z "$src" ] || [ ! -f "$src" ]; then
	echo "usage: $0 <path/to/RESULTS.md> [output]" >&2
	exit 2
fi

sum=$(sha256sum "$src" | cut -d' ' -f1)
today=$(date -u +%Y-%m-%d)
tmp="$out.tmp.$$"
trap 'rm -f "$tmp"' EXIT

{
	echo "# Generated by tools/gen-hwstatus.sh -- do not edit; edit RESULTS.md and re-run."
	echo "# source: befunde/RESULTS.md (github.com/SirRenix/minisforum-n5pro-fan-proxmox)"
	echo "# source-sha256: $sum"
	echo "# generated: $today"
	echo "# columns: product	board	bios	ec	status	origin	date	note"
	awk '
		/<!-- hwstatus:begin -->/ { on = 1; next }
		/<!-- hwstatus:end -->/   { on = 0; done = 1; next }
		!on { next }
		/^[[:space:]]*$/ { next }
		{
			line = $0
			gsub(/`/, "", line)
			sub(/^[[:space:]]*\|/, "", line)
			sub(/\|[[:space:]]*$/, "", line)
			n = split(line, c, "|")
			if (n != 8) { printf "RESULTS.md:%d: %d columns, want 8\n", NR, n > "/dev/stderr"; bad = 1; next }
			for (i = 1; i <= n; i++) { gsub(/^[[:space:]]+|[[:space:]]+$/, "", c[i]); gsub(/\t/, " ", c[i]) }
			if (c[1] == "Produkt" || c[1] ~ /^-+$/) next
			if (c[5] !~ /^(validated|tested|experimental|unknown)$/) {
				printf "RESULTS.md:%d: unknown status %s\n", NR, c[5] > "/dev/stderr"; bad = 1; next
			}
			if (c[5] ~ /^(validated|tested)$/ && c[6] != "eigen") {
				printf "RESULTS.md:%d: status %s needs origin eigen, not %s\n", NR, c[5], c[6] > "/dev/stderr"; bad = 1; next
			}
			printf "%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n", c[1], c[2], c[3], c[4], c[5], c[6], c[7], c[8]
			rows++
		}
		END {
			if (!done) { print "RESULTS.md: hwstatus markers not found" > "/dev/stderr"; exit 1 }
			if (bad) exit 1
			if (rows == 0) { print "RESULTS.md: empty hwstatus table" > "/dev/stderr"; exit 1 }
		}
	' "$src"
} > "$tmp"
mv "$tmp" "$out"
trap - EXIT
echo "wrote $out from $src (sha256 $sum)"
